 const [search,setSearch]=useState(''),[status,setStatus]=useState('all'),[deptFilter,setDeptFilter]=useState('all'),[locFilter,setLocFilter]=useState('all'),[from,setFrom]=useState(''),[to,setTo]=useState('');
 const [modal,setModal]=useState<any>(null),[form,setForm]=useState<any>({}),[formError,setFormError]=useState(''),[tab,setTab]=useState('people'),[mmTab,setMmTab]=useState('open'),[bulk,setBulk]=useState(false),[shiftFilter,setShiftFilter]=useState('all'),[imp,setImp]=useState<any>(null),[importError,setImportError]=useState('');
 async function load(user=testUser){setError('');try{const r=await fetch('/api/state',{headers:user?{'x-demo-user':user}:{}});const v:any=await r.json();if(!r.ok){if(r.status===401)setData(null);throw new Error(v.error)}setData((previous:any)=>previous?.revision===v.revision&&previous.actor.id===v.actor.id?previous:v);}catch(e:any){setError(e.message)}}
