 const pending=s.supports.filter((r:any)=>r.status==='pending'),approved=s.supports.filter((r:any)=>counted(s,r,idx)),allIssues=s.supports.flatMap((r:any)=>issues(s,r,idx).map((v:any)=>({...v,request:r}))),unresolved=allIssues.filter((x:any)=>!x.request.issueResolved&&isActive(x.request)),inbox=filtered.filter((r:any)=>canDecide(u,r));
