 function supportForm(r?:any){open('support',r?{...r}:{fromDept:admin?s.departments[0]?.id:u.deptIds[0],toDept:s.departments.find((d:any)=>d.id!==(admin?s.departments[0]?.id:u.deptIds[0]))?.id,personIds:[],start:today()+'T09:00',end:today()+'T12:00',breakMinutes:0,realized:instant(today()+'T12:00')<=new Date(),note:'',shiftId:null})}
