 function requestTable(rows:any[],small=false){return rows.length?<div className="table-scroll"><table><thead><tr><th>DESTEK / TARİH</th><th>BÖLÜMLER ARASI AKIŞ</th><th>PERSONEL</th><th>TÜR</th><th>DURUM</th><th><span className="sr-only">İşlemler</span></th></tr></thead><tbody>{rows.map((r:any)=>{const is=issues(s,r,idx);return <tr key={r.id} onClick={()=>open('detail',r)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&open('detail',r)}><td><strong className="code">{r.code}</strong><small>{dateLabel(r.start.slice(0,10))} · {r.start.slice(11)}–{r.end.slice(11)}{r.end.slice(0,10)!==r.start.slice(0,10)?' (+1 gün)':''}</small></td><td><div className="flow"><span>{deptName(r.fromDept)}</span><ArrowRight size={14}/><strong>{deptName(r.toDept)}</strong></div><small>{loc(dept(r.toDept)?.locationId)?.name}</small></td><td><div className="avatar-stack">{r.personIds.slice(0,3).map((id:string)=><span key={id} title={person(id)?.name}>{person(id)?.name.split(' ').map((n:string)=>n[0]).join('')}</span>)}<em>{r.personIds.length} kişi</em></div>{is.length>0&&!r.issueResolved&&<small className="orange"><TriangleAlert size={11}/> {is.length} kontrol uyarısı</small>}</td><td><strong>{r.realized?'Gerçekleşen':'Planlanan'}</strong><small>{r.personIds.length} kişi</small></td><td><Badge status={r.status==='cancelled'?'rejected':r.status}>{statusName[r.status]}</Badge>{r.source==='auto'&&r.status==='approved'&&<small className="auto-label">Sistem onayı</small>}{r.status==='cancelled'&&<small className="auto-label">{cancelName(r)}</small>}</td><td><ChevronRight size={16}/></td></tr>})}</tbody></table></div>:<Empty/>}
